// edges hold {u, v, w}. Fills dist; returns false on a negative cycle.
bool bellmanFord(int n, vector<array<int,3>>& edges, int src,
                 vector<long long>& dist) {
    const long long INF = 1e18;
    dist.assign(n, INF); dist[src] = 0;
    for (int it = 0; it < n - 1; ++it)              // V-1 relaxation rounds
        for (auto& e : edges)
            if (dist[e[0]] != INF && dist[e[0]] + e[2] < dist[e[1]])
                dist[e[1]] = dist[e[0]] + e[2];
    for (auto& e : edges)                            // extra round detects cycle
        if (dist[e[0]] != INF && dist[e[0]] + e[2] < dist[e[1]])
            return false;
    return true;
}

def bellman_ford(n, edges, src):
    INF = float('inf')
    dist = [INF]*n; dist[src] = 0
    for _ in range(n - 1):
        for u, v, w in edges:
            if dist[u] != INF and dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
    for u, v, w in edges:                 # extra round
        if dist[u] != INF and dist[u] + w < dist[v]:
            return None                   # negative cycle
    return dist

class Solution {
public:
    int findCheapestPrice(int n, vector<vector<int>>& flights, int src, int dst, int K) {
        const int INF = 1e9;
        vector<int> dist(n, INF); dist[src] = 0;
        for (int i = 0; i <= K; i++) {
            vector<int> tmp = dist;
            for (auto& f : flights)
                if (dist[f[0]] != INF) tmp[f[1]] = min(tmp[f[1]], dist[f[0]] + f[2]);
            dist = tmp;
        }
        return dist[dst] == INF ? -1 : dist[dst];
    }
};

class Solution:
    def findCheapestPrice(self, n, flights, src, dst, K):
        INF = float('inf')
        dist = [INF] * n
        dist[src] = 0
        for _ in range(K + 1):
            tmp = dist[:]
            for u, v, w in flights:
                if dist[u] + w < tmp[v]:
                    tmp[v] = dist[u] + w
            dist = tmp
        return -1 if dist[dst] == INF else dist[dst]

class Solution {
public:
    int networkDelayTime(vector<vector<int>>& times, int n, int k) {
        const int INF = 1e9;
        vector<int> dist(n + 1, INF); dist[k] = 0;
        for (int i = 1; i < n; i++)
            for (auto& t : times)
                if (dist[t[0]] != INF) dist[t[1]] = min(dist[t[1]], dist[t[0]] + t[2]);
        int ans = 0;
        for (int i = 1; i <= n; i++) ans = max(ans, dist[i]);
        return ans == INF ? -1 : ans;
    }
};

class Solution:
    def networkDelayTime(self, times, n, k):
        INF = float('inf')
        dist = [INF] * (n + 1)
        dist[k] = 0
        for _ in range(n - 1):
            for u, v, w in times:
                if dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w
        ans = max(dist[1:])
        return -1 if ans == INF else ans

class Solution {
public:
    bool hasNegativeCycle(int n, vector<vector<int>>& edges) {
        vector<long long> dist(n, 0);          // virtual source to all
        for (int i = 0; i < n - 1; i++)
            for (auto& e : edges)
                if (dist[e[0]] + e[2] < dist[e[1]]) dist[e[1]] = dist[e[0]] + e[2];
        for (auto& e : edges)
            if (dist[e[0]] + e[2] < dist[e[1]]) return true;   // still relaxes
        return false;
    }
};

class Solution:
    def hasNegativeCycle(self, n, edges):
        dist = [0] * n
        for _ in range(n - 1):
            for u, v, w in edges:
                if dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w
        for u, v, w in edges:
            if dist[u] + w < dist[v]:
                return True
        return False

#include <cmath>
class Solution {
public:
    bool arbitrage(int n, vector<vector<double>>& rates) {  // rates: {u, v, rate}
        vector<double> dist(n, 0.0);
        vector<array<double,3>> edges;
        for (auto& r : rates) edges.push_back({r[0], r[1], -log(r[2])});
        for (int i = 0; i < n - 1; i++)
            for (auto& e : edges) {
                int u = (int)e[0], v = (int)e[1];
                if (dist[u] + e[2] < dist[v] - 1e-9) dist[v] = dist[u] + e[2];
            }
        for (auto& e : edges) {
            int u = (int)e[0], v = (int)e[1];
            if (dist[u] + e[2] < dist[v] - 1e-9) return true;
        }
        return false;
    }
};

import math
class Solution:
    def arbitrage(self, n, rates):   # rates: list of (u, v, rate)
        dist = [0.0] * n
        edges = [(u, v, -math.log(r)) for u, v, r in rates]
        for _ in range(n - 1):
            for u, v, w in edges:
                if dist[u] + w < dist[v] - 1e-9:
                    dist[v] = dist[u] + w
        for u, v, w in edges:
            if dist[u] + w < dist[v] - 1e-9:
                return True
        return False

class Solution {
public:
    vector<long long> shortestPaths(int n, vector<vector<int>>& edges, int src) {
        const long long INF = 1e18;
        vector<long long> dist(n, INF); dist[src] = 0;
        for (int i = 0; i < n - 1; i++)
            for (auto& e : edges)
                if (dist[e[0]] != INF && dist[e[0]] + e[2] < dist[e[1]])
                    dist[e[1]] = dist[e[0]] + e[2];
        return dist;
    }
};

class Solution:
    def shortestPaths(self, n, edges, src):
        INF = float('inf')
        dist = [INF] * n
        dist[src] = 0
        for _ in range(n - 1):
            for u, v, w in edges:
                if dist[u] != INF and dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w
        return dist
